### REQ-004: Encryption Key Rotation for Data at Rest

**Requirement Statement:**
All MSK clusters MUST enable encryption at rest using AWS KMS Customer Managed Keys (CMKs). KMS keys MUST rotate automatically on an annual basis per PCI DSS Requirement 3.6.4. Key rotation MUST not disrupt cluster operations. Key usage MUST be monitored via CloudWatch metrics and CloudTrail logs.

**Rationale:**
Encryption at rest protects data stored on MSK broker EBS volumes from unauthorized access. HIPAA §164.312(a)(2)(iv) requires encryption of ePHI at rest. Annual key rotation limits cryptographic key exposure window and meets PCI DSS compliance requirements.

**Verification Method:**
- KMS key rotation policy validation via Terraform
- CloudTrail audit log review for KMS API calls (Encrypt, Decrypt, GenerateDataKey)
- Quarterly KMS key usage reporting
- Annual key rotation compliance check

**KMS Key Configuration (Terraform):**

```hcl
# Customer Managed Key for MSK cluster encryption
resource "aws_kms_key" "msk_cluster" {
  description             = "KMS key for MSK cluster ${var.cluster_name} encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true  # Automatic annual rotation

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow MSK Service"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "kafka.${var.region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.region}.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/msk/*"
          }
        }
      }
    ]
  })

  tags = {
    Name        = "msk-${var.cluster_name}-cmk"
    Cluster     = var.cluster_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_kms_alias" "msk_cluster" {
  name          = "alias/msk/${var.cluster_name}"
  target_key_id = aws_kms_key.msk_cluster.key_id
}

# CloudWatch alarm for KMS key usage anomalies
resource "aws_cloudwatch_metric_alarm" "kms_decrypt_excessive" {
  alarm_name          = "msk-${var.cluster_name}-kms-decrypt-excessive"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "2"
  metric_name         = "UserErrorCount"
  namespace           = "AWS/KMS"
  period              = "300"
  statistic           = "Sum"
  threshold           = "100"
  alarm_description   = "Excessive KMS decrypt errors for MSK cluster ${var.cluster_name}"
  treat_missing_data  = "notBreaching"

  dimensions = {
    KeyId = aws_kms_key.msk_cluster.key_id
  }

  alarm_actions = [var.security_sns_topic_arn]
}
```

**MSK Cluster with Encryption at Rest:**

```hcl
resource "aws_msk_cluster" "main" {
  cluster_name           = var.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = var.broker_count

  broker_node_group_info {
    instance_type   = var.broker_instance_type
    client_subnets  = var.private_subnet_ids
    security_groups = [aws_security_group.msk_cluster.id]

    storage_info {
      ebs_storage_info {
        volume_size = var.broker_volume_size
        provisioned_throughput {
          enabled           = true
          volume_throughput = var.broker_volume_throughput
        }
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_cluster.arn  # Customer Managed Key

    encryption_in_transit {
      client_broker = "TLS"           # Require TLS for client-broker
      in_cluster    = true            # Require TLS for broker-broker
    }
  }

  client_authentication {
    sasl {
      iam = true  # Enable IAM authentication
    }

    tls {
      certificate_authority_arns = [
        var.private_ca_arn  # For mTLS authentication
      ]
    }
  }

  configuration_info {
    arn      = aws_msk_configuration.main.arn
    revision = aws_msk_configuration.main.latest_revision
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      s3 {
        enabled = true
        bucket  = var.msk_logs_s3_bucket
        prefix  = "broker-logs/${var.cluster_name}/"
      }
    }
  }

  tags = {
    Name        = var.cluster_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}
