**KMS Key Rotation Compliance Check (Python):**

```python
#!/usr/bin/env python3
"""
KMS Key Rotation Compliance Checker
Validates annual key rotation is enabled for all MSK cluster KMS keys.
"""

import boto3
import sys
from typing import List, Dict

kms = boto3.client('kms')
kafka = boto3.client('kafka')

def get_msk_clusters() -> List[Dict]:
    """Retrieve all MSK clusters."""
    clusters = []
    paginator = kafka.get_paginator('list_clusters_v2')

    for page in paginator.paginate():
        for cluster in page['ClusterInfoList']:
            clusters.append({
                'ClusterArn': cluster['ClusterArn'],
                'ClusterName': cluster['ClusterName'],
                'State': cluster['State']
            })

    return clusters

def get_cluster_kms_key(cluster_arn: str) -> str:
    """Get KMS key ARN for MSK cluster."""
    response = kafka.describe_cluster_v2(ClusterArn=cluster_arn)

    encryption_info = response['ClusterInfo'].get('EncryptionInfo', {})
    encryption_at_rest = encryption_info.get('EncryptionAtRest', {})

    return encryption_at_rest.get('DataVolumeKMSKeyId')

def check_key_rotation(key_id: str) -> bool:
    """Check if KMS key has automatic rotation enabled."""
    try:
        response = kms.get_key_rotation_status(KeyId=key_id)
        return response['KeyRotationEnabled']
    except kms.exceptions.NotFoundException:
        print(f"  WARNING: Key {key_id} not found")
        return False
    except Exception as e:
        print(f"  ERROR checking key rotation: {e}")
        return False

def main():
    print("=" * 80)
    print("MSK KMS Key Rotation Compliance Check")
    print("=" * 80)

    clusters = get_msk_clusters()
    print(f"\nFound {len(clusters)} MSK clusters\n")

    violations = []

    for cluster in clusters:
        cluster_name = cluster['ClusterName']
        print(f"Checking cluster: {cluster_name}")

        # Skip non-ACTIVE clusters
        if cluster['State'] != 'ACTIVE':
            print(f"  Skipping (state: {cluster['State']})")
            continue

        # Get KMS key
        kms_key_arn = get_cluster_kms_key(cluster['ClusterArn'])

        if not kms_key_arn:
            violations.append(f"{cluster_name}: No KMS key configured (encryption at rest disabled)")
            print(f"  ❌ VIOLATION: No KMS key configured")
            continue

        # Check if rotation enabled
        rotation_enabled = check_key_rotation(kms_key_arn)

        if rotation_enabled:
            print(f"  ✅ Key rotation enabled")
        else:
            violations.append(f"{cluster_name}: KMS key rotation disabled (Key: {kms_key_arn})")
            print(f"  ❌ VIOLATION: Key rotation disabled")

    # Report results
    print("\n" + "=" * 80)
    if violations:
        print(f"COMPLIANCE CHECK FAILED: {len(violations)} violations found")
        print("=" * 80)
        for violation in violations:
            print(f"  - {violation}")
        sys.exit(1)
    else:
        print("COMPLIANCE CHECK PASSED: All MSK clusters have KMS key rotation enabled")
        print("=" * 80)
        sys.exit(0)

if __name__ == "__main__":
    main()
```

