### Configuration Specifications

**MSK Cluster Security Configuration:**

```hcl
# Required MSK cluster security settings
resource "aws_msk_cluster" "main" {
  cluster_name            = var.cluster_name
  kafka_version           = "3.6.0"
  number_of_broker_nodes  = var.broker_count

  # REQUIRED: IAM authentication
  client_authentication {
    sasl {
      iam = true  # MANDATORY
    }
  }

  # REQUIRED: Encryption at rest with CMK
  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_encryption.arn  # MANDATORY: CMK, not AWS managed
  }

  # REQUIRED: Encryption in transit
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"     # MANDATORY: TLS or TLS_PLAINTEXT is PROHIBITED
      in_cluster    = true      # MANDATORY: broker-to-broker encryption
    }
  }

  # REQUIRED: Logging to CloudWatch
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true                                      # MANDATORY
        log_group = aws_cloudwatch_log_group.msk_logs.name  # MANDATORY: 365-day retention
      }
      s3 {
        enabled = true                                        # MANDATORY for long-term retention
        bucket  = aws_s3_bucket.msk_audit_logs.id           # MANDATORY: 7-year retention
        prefix  = "msk-broker-logs/"
      }
    }
  }
}
```

