#### Continuous Compliance Monitoring

**CloudWatch Dashboard (Terraform):**

```hcl
resource "aws_cloudwatch_dashboard" "msk_security_compliance" {
  dashboard_name = "MSK-Security-Compliance-${var.environment}"

  dashboard_body = jsonencode({
    widgets = [
      {
        type = "metric"
        properties = {
          title  = "Authentication Failures (Last 7 Days)"
          region = var.region
          metrics = [
            ["AWS/Kafka", "AuthenticationFailures", { stat = "Sum", label = "Auth Failures" }]
          ]
          period = 300
          stat   = "Sum"
          yAxis = {
            left = { min = 0 }
          }
        }
      },
      {
        type = "metric"
        properties = {
          title  = "Unauthorized Access Attempts"
          region = var.region
          metrics = [
            ["AWS/Kafka", "ClientConnectionCount", { stat = "Sum", label = "Failed Connections" }]
          ]
          period = 300
        }
      },
      {
        type = "log"
        properties = {
          title  = "Recent ACL Violations"
          region = var.region
          query  = <<-EOT
            SOURCE '/aws/msk/${var.cluster_name}/broker-logs'
            | fields @timestamp, @message
            | filter @message like /AUTHORIZATION_FAILED/
            | sort @timestamp desc
            | limit 50
          EOT
        }
      },
      {
        type = "metric"
        properties = {
          title  = "Certificates Expiring <30 Days"
          region = var.region
          metrics = [
            ["AWS/CertificateManager", "DaysToExpiry", { stat = "Minimum" }]
          ]
          period = 86400
          yAxis = {
            left = { min = 0, max = 90 }
          }
        }
      }
    ]
  })
}
```

**Daily Security Metric Publisher (Lambda):**

```python
import boto3
import datetime

cloudwatch = boto3.client('cloudwatch')
kafka = boto3.client('kafka')
kms = boto3.client('kms')
acm = boto3.client('acm')

def lambda_handler(event, context):
    """Publish custom security compliance metrics daily."""

    namespace = 'MSK/SecurityCompliance'
    timestamp = datetime.datetime.utcnow()

    # Metric 1: Clusters with ACLs enabled
    clusters_with_acls = count_clusters_with_acls()
    cloudwatch.put_metric_data(
        Namespace=namespace,
        MetricData=[{
            'MetricName': 'ClustersWithACLs',
            'Value': clusters_with_acls,
            'Timestamp': timestamp,
            'Unit': 'Count'
        }]
    )

    # Metric 2: Certificates expiring soon (<30 days)
    expiring_certs = count_expiring_certificates(days=30)
    cloudwatch.put_metric_data(
        Namespace=namespace,
        MetricData=[{
            'MetricName': 'CertificatesExpiringSoon',
            'Value': expiring_certs,
            'Timestamp': timestamp,
            'Unit': 'Count'
        }]
    )

    # Metric 3: KMS keys with rotation disabled
    keys_without_rotation = count_keys_without_rotation()
    cloudwatch.put_metric_data(
        Namespace=namespace,
        MetricData=[{
            'MetricName': 'KMSKeysWithoutRotation',
            'Value': keys_without_rotation,
            'Timestamp': timestamp,
            'Unit': 'Count'
        }]
    )

    return {'statusCode': 200, 'body': 'Metrics published'}
```
